parameters.jsCode:
// Run Once for All Items. Input = 0..6 items from "Postgres PGVector Store" (Get Many): { document: { pageContent, metadata }, score }.
// When nothing matched, the store node emits ONE empty item (Always Output Data) so the workflow still reaches Respond.
// SCORE SEMANTICS (n8n 2.45.5, @langchain/community 1.1.27): score = RAW pgvector cosine DISTANCE (<=>, 0 = identical,
// 1 = orthogonal, 2 = opposite) -> LOWER IS BETTER. best_score = min(score). See n8n/README.md "Retrieval score semantics".
const extract = $('Extract').first().json;
// The LLM human message wraps excerpts / history / question in <excerpts>, <history>, <question> tags. Strip those
// tags from the untrusted text so a guest (or the PDF) cannot close a block early and smuggle in instructions.
const untag = (s) => String(s).replace(/<\s*\/?\s*(excerpts|history|question)\s*>/gi, '');

const hits = $input.all()
  .map((item) => item.json)
  .filter((j) => j && j.document && typeof j.document.pageContent === 'string' && j.document.pageContent.trim() !== '');

// chunk metadata has no chunk_index (only loc.lines) -> chunk_index = retrieval rank (0 = closest)
const sources = hits.map((h, i) => ({ chunk_index: i, score: Math.round(Number(h.score) * 10000) / 10000 }));
const scores = sources.map((s) => s.score).filter((s) => Number.isFinite(s));
const best_score = scores.length ? Math.min(...scores) : null;

const context = hits.map((h, i) => '[' + (i + 1) + '] ' + untag(h.document.pageContent.trim())).join('\n\n');

const history = (Array.isArray(extract.history) ? extract.history : []).slice(-8)
  .filter((m) => m && typeof m.content === 'string' && m.content.trim() !== '')
  .map((m) => (m.role === 'assistant' ? 'Assistant: ' : 'Guest: ') + untag(m.content.trim()))
  .join('\n');

return [{
  json: {
    context,
    best_score,
    n_chunks: hits.length,
    sources,
    question: untag(String(extract.question ?? '')).trim(),
    history: history || '(no previous messages)',
    document_id: extract.document_id,
  },
}];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "answer": {
      "type": "string",
      "description": "Reply to the guest (max ~120 words) using only facts from the excerpts, or exactly \"I'm sorry, I don't have that information right now.\" when the excerpts do not contain the information or the question is not about Cincinnati Hotel."
    },
    "category": {
      "type": "string",
      "enum": [
        "Rooms",
        "Restaurant & Dining",
        "Amenities & Facilities",
        "Pricing & Booking",
        "Location & Transport",
        "Policies",
        "Events",
        "Other"
      ],
      "description": "Topic of the guest's question (exactly one): Rooms = room types and suites, beds, views, occupancy, in-room features, the nightly price of a specific room; Restaurant & Dining = restaurants, bars, breakfast, room service, menus, meal times; Amenities & Facilities = pool, gym, spa, Wi-Fi, business center, laundry and any other on-site facility or service (including ones the hotel may not have); Pricing & Booking = general rates, deposits, payment, reservations, cancellations, check-in and check-out times; Location & Transport = address, directions, airport transfers, shuttle, parking, nearby attractions; Policies = pets, smoking, children, ID, accessibility, house rules; Events = weddings, meetings, conferences, ballrooms and event spaces; Other = greetings, thanks, goodbyes, questions that are not about the hotel, or anything that fits none of the above."
    },
    "answered": {
      "type": "boolean",
      "description": "true if the excerpts answer the question (fully or partially) or it is a pure greeting/thanks/goodbye; false otherwise, including questions that are not about Cincinnati Hotel."
    },
    "partial": {
      "type": "boolean",
      "description": "true only when answered is true and the excerpts cover some but not all parts of a multi-part question (the answer then covers only those parts); false when fully answered, not answered, or a greeting."
    }
  },
  "required": [
    "answer",
    "category",
    "answered",
    "partial"
  ],
  "additionalProperties": false
}

