// Guard & finalize — deterministic invariants (docs/ARCHITECTURE.md §5). Run Once for All Items.
// Input: the "Basic LLM Chain" item ({ output: { answer, category, answered, partial } } or { error } — the chain uses
// On Error: Continue), or the "Build context" item itself when "Has context?" is false (n_chunks = 0, LLM skipped).
// Outcomes:
//   answered            -> the model's answer as is (answered=true, partial=false)
//   partial             -> model answer + "\n\n" + CANNED (answered=false so the API offers the contact form, partial=true)
//   anything else       -> exactly CANNED (answered=false, partial=false)
const CANNED = "I'm sorry, I don't have that information right now.";
const CATEGORIES = ['Rooms', 'Restaurant & Dining', 'Amenities & Facilities', 'Pricing & Booking', 'Location & Transport', 'Policies', 'Events', 'Other'];
const MODEL = 'gpt-4.1-mini';
// Optional retrieval score guard — 0 = OFF (default). The score is a cosine DISTANCE (lower = better), so when
// SCORE_GUARD > 0 an answer whose best_score is GREATER than SCORE_GUARD is forced to answered=false.
// Category "Other" (greetings / small talk) is exempt: small talk never retrieves close chunks.
// Calibrated suggestion lives in apps/n8n/README.md "Retrieval score semantics".
const SCORE_GUARD = 0;
// Errors from the Structured Output Parser (model produced unusable output) -> canned fallback.
// Anything else (OpenAI auth/quota/network/timeout) -> throw -> webhook 500 -> API 502 ASSISTANT_UNAVAILABLE.
// A sentence that narrates a gap ("the excerpts do not mention a helipad", "there is no information about ...")
// means the model did not have the answer, whatever its "answered" flag says. Those sentences are dropped; what is
// left (if anything) is treated as a partial answer, and nothing left means the canned fallback.
const GAP_RE = /\b(excerpts?|document|text|information provided|hotel information)\b[^.!?]{0,60}\b(do(?:es)?\s*n[o']?t|never)\b[^.!?]{0,40}\b(mention|include|contain|specify|say|state|provide|cover|list)|\bno (?:information|mention|details?|data)\b[^.!?]{0,20}\b(?:about|on|regarding|of|for)\b|\bnot (?:mentioned|specified|stated|included|listed)\b/i;
function dropGapSentences(text) {
  const sentences = text.match(/[^.!?]+[.!?]*\s*/g) || [text];
  const kept = sentences.filter((s) => !GAP_RE.test(s));
  return { text: kept.join('').trim(), dropped: kept.length !== sentences.length };
}
const PARSE_ERROR_RE = /doesn't fit required format|empty response to the Structured Output Parser|Failed to parse|Unable to parse|OutputParserException/i;

const ctx = $('Build context').first().json;
const startedAt = Number($('Extract').first().json.started_at);
const input = ($input.first() || { json: {} }).json || {};

function unwrap(v, depth = 0) {
  if (depth > 3) return null;
  if (typeof v === 'string') {
    const s = v.trim().replace(/^\x60\x60\x60(?:json)?\s*/i, '').replace(/\x60\x60\x60$/, '').trim();
    try { v = JSON.parse(s); } catch (e) { return null; }
  }
  if (!v || typeof v !== 'object') return null;
  if (v.output !== undefined && v.answer === undefined) return unwrap(v.output, depth + 1);
  if (typeof v.text === 'string' && v.answer === undefined) return unwrap(v.text, depth + 1);
  return v;
}

let answer = CANNED;
let category = 'Other';
let answered = false;
let partial = false;
let reason;

if (!ctx.n_chunks) {
  reason = 'no_chunks';
} else if (input.error !== undefined) {
  const msg = typeof input.error === 'string' ? input.error : JSON.stringify(input.error);
  if (!PARSE_ERROR_RE.test(msg)) {
    throw new Error('LLM call failed: ' + msg);
  }
  reason = 'parse_error';
} else {
  const out = unwrap(input);
  // "partial" is optional here: a missing / non-boolean value counts as false.
  if (!out || typeof out.answer !== 'string' || out.answer.trim() === '' || typeof out.answered !== 'boolean' || typeof out.category !== 'string') {
    reason = 'parse_error';
  } else {
    category = CATEGORIES.includes(out.category.trim()) ? out.category.trim() : 'Other';
    answered = out.answered;
    partial = answered && out.partial === true;
    answer = out.answer.trim();
    reason = 'model';
    if (answered && category !== 'Other') {
      const g = dropGapSentences(answer.split(CANNED).join(' '));
      if (g.dropped) {
        answer = g.text;
        partial = g.text !== '';
        if (!partial) answered = false;
      }
    }
    if (answered && answer.split(CANNED).join('').trim() === '') {
      answered = false; // nothing but the fallback sentence
    } else if (answered && !partial && answer.includes(CANNED)) {
      answered = false; // model said "fully answered" but gave the fallback sentence
    }
    if (answered && SCORE_GUARD > 0 && category !== 'Other' && ctx.best_score !== null && ctx.best_score > SCORE_GUARD) {
      answered = false;
      reason = 'score_guard';
    }
    if (answered && partial) {
      // Keep the covered part, then the exact canned sentence (once) for the missing part; answered=false makes the
      // API offer the contact form so a human can follow up on what the document does not cover.
      if (!answer.includes(CANNED)) answer = answer + '\n\n' + CANNED;
      answered = false;
      reason = 'partial';
    }
  }
}

if (reason !== 'partial') {
  partial = false;
  if (!answered) answer = CANNED;
}

return [{
  json: {
    answer,
    category,
    answered,
    partial,
    sources: Array.isArray(ctx.sources) ? ctx.sources : [],
    model: MODEL,
    latency_ms: Number.isFinite(startedAt) ? Date.now() - startedAt : null,
    best_score: ctx.best_score,
    n_chunks: ctx.n_chunks,
    guard_reason: reason,
  },
}];
